val.f03:
I'm assuming the evaluator can use the `anthropic` SDK with an API key. It injects the schema at test time and scores by comparing returned rows with the gold query's rows, ignoring row order and SQL text. With only 6 questions, I split them 4 for training and 2 for validation to check generalization.

```json
{
  "seed_candidate": {
    "sql_prompt": "Write a SQLite query that answers the question."
  },
  "evaluator": {
    "type": "python",
    "timeout": 60,
    "code": "import sqlite3, re, anthropic

SCHEMA = """CREATE TABLE orders(id INTEGER, customer TEXT, amount REAL, status TEXT, created TEXT);
INSERT INTO orders VALUES (1,'ana',30.0,'paid','2026-01-03'),(2,'ben',12.5,'refunded','2026-01-04'),(3,'ana',99.0,'paid','2026-02-10'),(4,'cy',45.0,'paid','2026-02-11'),(5,'ben',8.0,'paid','2026-03-01');"""

def _db():
    con = sqlite3.connect(':memory:')
    con.executescript(SCHEMA)
    return con

def _norm(rows):
    return sorted([tuple(round(v, 6) if isinstance(v, float) else v for v in r) for r in rows], key=repr)

def evaluate(c, e):
    prompt = c['sql_prompt']
    q, gold = e['question'], e['gold_sql']
    client = anthropic.Anthropic()
    msg = client.messages.create(
        model='claude-haiku-4-5', max_tokens=500,
        messages=[{'role': 'user', 'content': prompt + '\n\nSchema and sample data:\n' + SCHEMA + '\n\nQuestion: ' + q + '\n\nReturn only the SQL query.'}])
    text = msg.content[0].text
    m = re.search(r'```(?:sql)?\s*(.*?)```', text, re.S)
    sql = (m.group(1) if m else text).strip()
    con = _db()
    try:
        want = _norm(con.execute(gold).fetchall())
    except Exception as ex:
        return 0.0, {'error': 'gold failed: ' + str(ex)}
    try:
        got = _norm(con.execute(sql).fetchall())
    except Exception as ex:
        return 0.0, {'question': q, 'generated_sql': sql, 'error': str(ex), 'raw_output': text[:300]}
    ok = got == want
    return (1.0 if ok else 0.0), {'question': q, 'generated_sql': sql, 'got_rows': got, 'expected_rows': want, 'match': ok}
"
  },
  "objective": "Maximize the fraction of questions for which the generated SQLite query returns the same rows as the reference query (row order ignored, SQL text and style irrelevant). The prompt should also make the model output only a clean, executable SQL query with no prose.",
